(function(E){ const x = E["exam-10"] = E["exam-10"] || {units:{}}; (x.units = x.units || {})["x10-s"] = {"id":"x10-s","patterns":["S1-frame","S1-food","S2-place","S3-consumer","TR-short","PARA-discuss"],"title":{"en":"Speaking","tr":"Speaking","fa":"Speaking (صحبت کردن)"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions about drinks with a detail, describe a place with a view for two minutes, and discuss beauty and advertising with a balanced view.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: içeceklerle ilgili günlük soruları bir ayrıntıyla cevaplayacak, manzaralı bir yeri iki dakika anlatacak ve güzellik ile reklamı dengeli bir görüşle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره درباره‌ی نوشیدنی‌ها با یک جزئیات جواب بدهی، دو دقیقه جایی با منظره را توصیف کنی و درباره‌ی زیبایی و تبلیغات با نظری متعادل بحث کنی."},"sessions":[["explain"],["sets"],["exit"]],"explain":{"title":{"en":"Speaking: Parts 1, 2 and 3","tr":"Speaking: Part 1, 2 ve 3","fa":"Speaking: بخش‌های ۱، ۲ و ۳"},"objective":{"en":"In this lesson you will learn to take the whole Speaking test: answer everyday questions about drinks with a detail, describe a place with a view for two minutes, and discuss beauty and advertising with a balanced view.","tr":"Bu derste Speaking sınavının tamamını yapmayı öğreneceksin: içeceklerle ilgili günlük soruları bir ayrıntıyla cevaplayacak, manzaralı bir yeri iki dakika anlatacak ve güzellik ile reklamı dengeli bir görüşle tartışacaksın.","fa":"در این درس یاد می‌گیری کل آزمون Speaking را انجام بدهی: به سؤال‌های روزمره درباره‌ی نوشیدنی‌ها با یک جزئیات جواب بدهی، دو دقیقه جایی با منظره را توصیف کنی و درباره‌ی زیبایی و تبلیغات با نظری متعادل بحث کنی."},"stats":[{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"11-14 min","tr":"11-14 dk","fa":"۱۱ تا ۱۴ دقیقه"}},{"label":{"en":"Parts","tr":"Kısım","fa":"بخش"},"value":"3"},{"label":{"en":"Part 2 talk","tr":"Part 2 konuşması","fa":"صحبت Part 2"},"value":{"en":"2 min","tr":"2 dk","fa":"۲ دقیقه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: tea and coffee, a view, beauty","tr":"Bu sınav: çay ve kahve, bir manzara, güzellik","fa":"این آزمون: چای و قهوه، یک منظره، زیبایی"},"intro":{"en":"Here the link between Part 2 and Part 3 is the word \"beautiful\": a beautiful view on the card, then beauty in advertising and everyday life. Expect Part 3 to move to a more abstract idea.","tr":"Burada Part 2 ile Part 3 arasındaki bağ \"güzel\" kelimesidir: kartta güzel bir manzara, sonra reklamda ve gündelik hayatta güzellik. Part 3’ün daha soyut bir fikre geçmesini bekle.","fa":"این‌جا پیوند Part 2 و Part 3 کلمه‌ی «زیبا» است: یک منظره‌ی زیبا روی کارت و بعد زیبایی در تبلیغات و زندگی روزمره. انتظار داشته باش Part 3 به ایده‌ای انتزاعی‌تر برود."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x10-s1-ctx","exam":true,"patterns":["S1-frame","S1-food"],"often":{"pattern":"S1-food","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 1: you, then tea and coffee","tr":"Part 1: sen, sonra çay ve kahve","fa":"Part 1: خودت، بعد چای و قهوه"},"asks":{"en":"The examiner checks your name and asks about your work, studies or home, then four questions on an everyday topic from the food and drink family: here, tea and coffee.","tr":"Sınav görevlisi adını kontrol eder, işini, okulunu ya da evini sorar, sonra yiyecek ve içecek ailesinden günlük bir konuda dört soru sorar: burada çay ve kahve.","fa":"ممتحن اسمت را چک می‌کند، درباره‌ی کار، درس یا خانه‌ات می‌پرسد و بعد چهار سؤال درباره‌ی یک موضوع روزمره از خانواده‌ی خوراکی و نوشیدنی: این‌جا چای و قهوه."},"fields":["Work or studies","Home","Tea or coffee?","When you drink it","Cafés","Changes over time"],"words":[{"a":"I prefer","b":"I’d rather have / I’m more of a ... person","tr":"tercih ederim","fa":"ترجیح می‌دهم"},{"a":"strong","b":"with a lot of flavour / black","tr":"koyu","fa":"پررنگ"},{"a":"a cup of","b":"a mug of / a glass of tea","tr":"bir fincan","fa":"یک فنجان"},{"a":"wake me up","b":"give me energy / keep me going","tr":"beni uyandırır","fa":"سرحالم می‌کند"},{"a":"a habit","b":"something I always do","tr":"alışkanlık","fa":"عادت"},{"a":"a coffee shop","b":"a café / a chain café","tr":"kahve dükkânı","fa":"کافی‌شاپ"},{"a":"herbal tea","b":"mint / camomile / fruit tea","tr":"bitki çayı","fa":"دمنوش"},{"a":"too much caffeine","b":"it keeps me awake at night","tr":"fazla kafein","fa":"کافئین زیاد"},{"a":"catch up with friends","b":"meet and chat","tr":"arkadaşlarla hasret gidermek","fa":"دیدار و گپ با دوست‌ها"},{"a":"these days","b":"nowadays / recently","tr":"bu günlerde","fa":"این روزها"}],"traps":[{"en":"Short yes/no answers. Say which, when or why, and add a small detail.","tr":"Kısa evet/hayır cevapları. Hangisi, ne zaman ya da neden olduğunu söyle ve küçük bir ayrıntı ekle.","fa":"جواب‌های کوتاه بله/نه. بگو کدام، کی یا چرا و یک جزئیات کوچک اضافه کن."},{"en":"Talking about tea in general, like a lecture. Part 1 is about your own habits.","tr":"Çay hakkında ders verir gibi genel konuşmak. Part 1 senin kendi alışkanlıklarınla ilgili.","fa":"حرف زدن کلی درباره‌ی چای مثل سخنرانی. Part 1 درباره‌ی عادت‌های خودت است."}],"example":{"text":"Examiner: \"Do you prefer tea or coffee?\"","item":"Which answer is best?","answer":"Tea, definitely. I have about five cups a day, usually black with a slice of lemon. Coffee makes me a bit nervous.","why":{"en":"A clear choice, a habit with a detail and a short reason.","tr":"Net bir seçim, ayrıntılı bir alışkanlık ve kısa bir neden.","fa":"انتخابی روشن، عادتی با جزئیات و یک دلیل کوتاه."}}},{"id":"x10-s2-ctx","exam":true,"patterns":["S2-place"],"often":{"pattern":"S2-place","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 2: a high place with a good view","tr":"Part 2: güzel manzaralı yüksek bir yer","fa":"Part 2: جایی بلند با منظره‌ای زیبا"},"asks":{"en":"The card asks you to describe a high place you have visited that had a beautiful view: where it was, how you got there, what you could see, and how you felt. Places are one of the most common Part 2 cards.","tr":"Kart, ziyaret ettiğin güzel manzaralı yüksek bir yeri anlatmanı istiyor: nerede olduğunu, oraya nasıl gittiğini, ne görebildiğini ve ne hissettiğini. Yerler en sık çıkan Part 2 kartlarından biridir.","fa":"کارت از تو می‌خواهد جایی بلند را که دیده‌ای و منظره‌ی زیبایی داشت توصیف کنی: کجا بود، چطور رفتی، چه می‌دیدی و چه حسی داشتی. مکان‌ها از رایج‌ترین کارت‌های Part 2 هستند."},"fields":["Where it was","How you got there","What you could see","How you felt"],"words":[{"a":"the top","b":"the summit / the highest point","tr":"zirve","fa":"قله، بالاترین نقطه"},{"a":"a climb","b":"a steep walk / a hike","tr":"tırmanış","fa":"کوه‌پیمایی، بالا رفتن"},{"a":"a cable car","b":"a lift that carries people up a mountain","tr":"teleferik","fa":"تله‌کابین"},{"a":"breathtaking","b":"stunning / spectacular","tr":"nefes kesici","fa":"نفس‌گیر"},{"a":"stretch out","b":"spread / reach as far as","tr":"uzanmak","fa":"گسترده بودن"},{"a":"in the distance","b":"far away / on the horizon","tr":"uzakta","fa":"در دوردست"},{"a":"a bird’s-eye view","b":"a view from high above","tr":"kuş bakışı","fa":"نمای از بالا"},{"a":"worth it","b":"it made the effort worthwhile","tr":"değdi","fa":"می‌ارزید"},{"a":"peaceful","b":"calm / quiet","tr":"huzurlu","fa":"آرام"},{"a":"I’ll never forget","b":"it has stayed with me","tr":"asla unutmayacağım","fa":"هرگز فراموش نمی‌کنم"}],"traps":[{"en":"Listing what you saw like a list of objects. Describe it from near to far, with colours and size.","tr":"Gördüklerini nesne listesi gibi sıralamak. Yakından uzağa, renkler ve büyüklükle anlat.","fa":"فهرست کردن چیزهایی که دیدی مثل فهرست اشیا. از نزدیک به دور، با رنگ و اندازه توصیف کن."},{"en":"Rushing the feeling line. \"Explain how you felt\" is where you show why the place mattered.","tr":"Duygu satırını aceleye getirmek. \"Ne hissettiğini açıkla\", yerin neden önemli olduğunu gösterdiğin yerdir.","fa":"سرسری گفتن خط احساس. «توضیح بده چه حسی داشتی» جایی است که نشان می‌دهی چرا آن مکان برایت مهم بود."}],"example":{"text":"Notes (one minute): hill above home town · early morning walk, 1 hr · town, river, mist, mountains far off · calm, proud","item":"How do you start?","answer":"I’d like to talk about a hill just outside my home town, which I climbed early one morning last spring.","why":{"en":"The first sentence answers \"where\" and sets the time.","tr":"İlk cümle \"nerede\" sorusunu cevaplıyor ve zamanı belirliyor.","fa":"جمله‌ی اول به «کجا» جواب می‌دهد و زمان را مشخص می‌کند."}}},{"id":"x10-s3-ctx","exam":true,"patterns":["S3-consumer","PARA-discuss","TR-short"],"often":{"pattern":"S3-consumer","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"Part 3: beauty, advertising and success","tr":"Part 3: güzellik, reklam ve başarı","fa":"Part 3: زیبایی، تبلیغات و موفقیت"},"asks":{"en":"The examiner moves from beautiful places to beauty in people’s lives: how advertising uses beauty, and whether appearance affects success. Six general questions in two groups.","tr":"Sınav görevlisi güzel yerlerden insanların hayatındaki güzelliğe geçer: reklamın güzelliği nasıl kullandığı ve görünüşün başarıyı etkileyip etkilemediği. İki grupta altı genel soru.","fa":"ممتحن از مکان‌های زیبا به زیبایی در زندگی آدم‌ها می‌رسد: تبلیغات چطور از زیبایی استفاده می‌کند و آیا ظاهر روی موفقیت اثر دارد. شش سؤال کلی در دو گروه."},"fields":["Beauty in advertising","Beauty products","Young people and images","Appearance at work","Changing ideas of beauty"],"words":[{"a":"advertisers","b":"companies that sell products / marketing","tr":"reklamcılar","fa":"تبلیغ‌کننده‌ها"},{"a":"unrealistic","b":"impossible to achieve / edited photos","tr":"gerçekçi olmayan","fa":"غیرواقعی"},{"a":"self-confidence","b":"feeling good about yourself","tr":"özgüven","fa":"اعتمادبه‌نفس"},{"a":"pressure","b":"feeling you must look a certain way","tr":"baskı","fa":"فشار"},{"a":"first impressions","b":"how people judge you at first","tr":"ilk izlenim","fa":"برداشت اول"},{"a":"appearance","b":"how someone looks","tr":"görünüş","fa":"ظاهر"},{"a":"standards of beauty","b":"what people consider attractive","tr":"güzellik ölçüleri","fa":"معیارهای زیبایی"},{"a":"it varies","b":"it differs from culture to culture","tr":"değişir","fa":"فرق می‌کند"},{"a":"to some extent","b":"partly / up to a point","tr":"bir ölçüde","fa":"تا حدی"},{"a":"in the long run","b":"over time / eventually","tr":"uzun vadede","fa":"در درازمدت"}],"traps":[{"en":"One-sided answers: Part 3 rewards a view plus the other side (\"to some extent, but...\").","tr":"Tek taraflı cevaplar: Part 3’te bir görüş ve karşı taraf (\"bir ölçüde, ama...\") değer kazanır.","fa":"جواب‌های یک‌طرفه: در Part 3 نظری همراه با طرف مقابل («تا حدی، اما...») ارزش دارد."},{"en":"Personal comments only: \"I don’t care about make-up.\" Widen it to people in general.","tr":"Yalnızca kişisel yorumlar: \"Makyaj umurumda değil.\" Bunu genel olarak insanlara genişlet.","fa":"فقط حرف شخصی: «برایم آرایش مهم نیست». آن را به آدم‌ها به‌طور کلی گسترش بده."}],"example":{"text":"Examiner: \"Does appearance help people succeed at work?\"","item":"What should the answer contain?","answer":"A view (to some extent), a reason (first impressions in interviews), an example (sales jobs), and the other side (skills matter more in the long run).","why":{"en":"Four moves make a balanced Part 3 answer.","tr":"Dört hamle dengeli bir Part 3 cevabı oluşturur.","fa":"چهار حرکت یک جواب متعادل Part 3 می‌سازد."}}},{"id":"S2-place","ctx":["S2-place"],"title":{"en":"A place","tr":"Bir yer","fa":"یک مکان"},"asks":{"en":"A card about a place: a garden or park, a place with a view, an attraction, the neighbourhood where you grew up, a city to visit, a hotel. The prompts ask where it is, what it is like, what you do there, and why it matters.","tr":"Bir yer hakkında kart: bir bahçe ya da park, manzaralı bir yer, bir turistik yer, büyüdüğün mahalle, gezilecek bir şehir, bir otel. Maddeler nerede olduğunu, neye benzediğini, orada ne yaptığını ve neden önemli olduğunu sorar.","fa":"کارتی درباره‌ی یک مکان: یک باغ یا پارک، جایی با منظره، یک جاذبه‌ی گردشگری، محله‌ای که در آن بزرگ شدی، شهری برای دیدن، یک هتل. بندها می‌پرسند کجاست، چه شکلی است، آنجا چه می‌کنی و چرا برایت مهم است."},"fields":["Describe a park or garden you like.","Describe a place with a beautiful view.","Describe a tourist attraction you would recommend.","Describe the neighbourhood where you grew up.","Describe a city you would like to visit."],"words":[{"a":"nice","b":"peaceful / charming / breathtaking","tr":"huzurlu, büyüleyici","fa":"آرام، دلنشین، نفس‌گیر"},{"a":"big","b":"huge / spacious","tr":"geniş","fa":"بزرگ و جادار"},{"a":"old","b":"historic / centuries old","tr":"tarihî","fa":"تاریخی"},{"a":"it is near","b":"it's a short walk from","tr":"... -e çok yakın","fa":"چند قدمی ... است"},{"a":"trees around it","b":"surrounded by trees","tr":"ağaçlarla çevrili","fa":"دورتادور درخت"},{"a":"you can see far","b":"it looks out over the whole valley","tr":"bütün vadiye bakıyor","fa":"رو به کل دره است"},{"a":"many tourists","b":"packed with tourists","tr":"turist kaynıyor","fa":"پر از توریست"},{"a":"I go there","b":"I tend to go there when","tr":"genelde ... oraya giderim","fa":"معمولاً وقتی ... آنجا می‌روم"},{"a":"I feel good there","b":"it makes me feel calm","tr":"bana huzur veriyor","fa":"آرامم می‌کند"},{"a":"I remember","b":"what sticks in my mind is","tr":"aklımda kalan","fa":"چیزی که در ذهنم مانده"},{"a":"you should go","b":"it's well worth a visit","tr":"kesinlikle görülmeye değer","fa":"واقعاً ارزش دیدن دارد"},{"a":"small details","b":"the smell of the pine trees","tr":"çam ağaçlarının kokusu","fa":"بوی درخت‌های کاج"}],"traps":[{"en":"Describing only what it looks like: use every prompt, and keep time for the \"explain\" line.","tr":"Yalnızca neye benzediğini anlatmak: her maddeyi kullan ve \"explain\" satırına zaman bırak.","fa":"فقط توصیف ظاهر: از همه‌ی بندها استفاده کن و برای خط «explain» وقت نگه دار."},{"en":"Present tenses for what it is like; past tenses for a visit you remember.","tr":"Neye benzediği için şimdiki zaman; hatırladığın bir ziyaret için geçmiş zaman.","fa":"برای اینکه چطور جایی است زمان حال؛ برای بازدیدی که یادت مانده زمان گذشته."}],"example":{"lines":[["Candidate","I’d like to talk about a hill just outside my hometown, about twenty minutes from my house by bike."],["Candidate","From the top you can see the whole valley, with the river shining in the middle."],["Candidate","What sticks in my mind is the first time I watched the sunrise there with my brother."]],"item":"Which prompts has the speaker covered so far?","answer":"Where it is, what you can see, and a memory that leads into why it matters.","why":{"en":"Three lines cover three prompts, and the memory prepares the \"explain\" line.","tr":"Üç satır üç maddeyi karşılıyor; anı da \"explain\" satırını hazırlıyor.","fa":"سه خط سه بند را پوشش می‌دهند و آن خاطره خط «explain» را آماده می‌کند."}},"ideas":["one thing you can see, hear or smell there","a short story of one visit","who you go with","how it has changed","why it matters to you (the \"explain\" line)"],"general":true,"patterns":["S2-place"],"often":{"pattern":"S2-place","n":7,"of":40,"label":{"en":"Comes up often in the real exam: 7 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ آزمون از ۴۰ آزمونِ اخیر"}}},{"id":"S3-consumer","ctx":["S3-consumer"],"title":{"en":"Consumers, money and advertising","tr":"Tüketiciler, para ve reklam","fa":"مصرف‌کننده، پول و تبلیغات"},"asks":{"en":"General questions linked to the Part 2 card, about advertising, reviews, luxury, wealth, impulse buying and celebrities. The examiner wants an opinion, a reason, an example and, when it helps, the other side.","tr":"Part 2 kartına bağlı, reklam, yorumlar, lüks, zenginlik, dürtüsel alışveriş ve ünlüler hakkında genel sorular. Sınav görevlisi bir görüş, bir neden, bir örnek ve gerektiğinde karşı tarafı ister.","fa":"سؤال‌های کلی مرتبط با کارت Part 2، درباره‌ی تبلیغات، نقدها، تجمل، ثروت، خرید هیجانی و افراد مشهور. ممتحن یک نظر، یک دلیل، یک مثال و هرجا لازم بود طرف مقابل را می‌خواهد."},"fields":["Should advertising be more honest?","Why do people buy things they do not need?","Do online reviews help shoppers?","Should celebrities advertise products?","Does money make people happy?"],"words":[{"a":"adverts lie","b":"advertising can be misleading","tr":"reklam yanıltıcı olabilir","fa":"تبلیغ ممکن است گمراه‌کننده باشد"},{"a":"buy without thinking","b":"impulse buying","tr":"dürtüsel alışveriş","fa":"خرید هیجانی"},{"a":"famous people","b":"celebrities / influencers","tr":"ünlüler","fa":"آدم‌های مشهور"},{"a":"rich","b":"wealthy / well off","tr":"varlıklı","fa":"ثروتمند"},{"a":"expensive things","b":"luxury goods","tr":"lüks ürünler","fa":"کالاهای لوکس"},{"a":"people want it","b":"there is huge demand for","tr":"büyük talep var","fa":"تقاضای زیادی هست"},{"a":"the law should stop it","b":"it should be regulated","tr":"düzenlenmeli","fa":"باید قانون‌گذاری شود"},{"a":"young people copy","b":"young people are easily influenced","tr":"gençler kolay etkilenir","fa":"جوان‌ها زود تحت تأثیر قرار می‌گیرند"},{"a":"it depends","b":"it depends on the situation","tr":"duruma bağlı","fa":"بستگی به شرایط دارد"},{"a":"on the other hand","b":"then again / that said","tr":"öte yandan","fa":"از طرف دیگر"},{"a":"in my experience","b":"from what I've seen","tr":"gördüğüm kadarıyla","fa":"تا جایی که دیده‌ام"},{"a":"in the long run","b":"over time","tr":"uzun vadede","fa":"در درازمدت"}],"traps":[{"en":"Part 3 is about people in general, not only you. Move from \"I\" to \"people\", \"society\", \"young people\".","tr":"Part 3 yalnızca seninle değil, genel olarak insanlarla ilgilidir. \"Ben\"den \"insanlar\", \"toplum\", \"gençler\"e geç.","fa":"Part 3 درباره‌ی آدم‌ها به‌طور کلی است، نه فقط تو. از «من» به «مردم»، «جامعه»، «جوان‌ها» برو."},{"en":"A one-sentence opinion is too short. Give the reason and an example before you stop.","tr":"Tek cümlelik görüş çok kısadır. Durmadan önce nedeni ve bir örneği ver.","fa":"نظر یک‌جمله‌ای خیلی کوتاه است. قبل از تمام کردن، دلیل و یک مثال بیاور."}],"example":{"lines":[["Examiner","Why do people buy things they don’t really need?"],["Candidate","I think mainly because shopping has become a kind of entertainment."],["Candidate","For example, many people scroll through shopping apps when they’re bored, and buy something just to feel better."],["Candidate","That said, some of it is simply clever advertising."]],"item":"Which moves does the answer make?","answer":"Opinion, reason, a specific example, then the other side (\"That said...\").","why":{"en":"Four short moves make a full Part 3 answer of about thirty seconds.","tr":"Dört kısa hamle yaklaşık otuz saniyelik tam bir Part 3 cevabı oluşturur.","fa":"چهار حرکت کوتاه یک جواب کامل Part 3 حدود سی‌ثانیه‌ای می‌سازد."}},"ideas":["adverts give useful information but create needs","reviews help, but some are fake","happiness needs enough money, not unlimited money","celebrity adverts influence teenagers most"],"general":true,"patterns":["S3-consumer"],"often":{"pattern":"S3-consumer","n":8,"of":40,"label":{"en":"Comes up often in the real exam: 8 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 8’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۸ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Three parts, one examiner","tr":"Üç kısım, bir sınav görevlisi","fa":"سه بخش، یک ممتحن"},"body":{"en":"Part 1 (4-5 minutes): questions about you and one everyday topic. Part 2 (3-4 minutes): one minute to prepare, then up to two minutes alone, then one short question. Part 3 (4-5 minutes): a discussion of general questions. The test is recorded.","tr":"Part 1 (4-5 dakika): seninle ve günlük bir konuyla ilgili sorular. Part 2 (3-4 dakika): bir dakika hazırlık, sonra iki dakikaya kadar tek başına konuşma, sonra kısa bir soru. Part 3 (4-5 dakika): genel soruların tartışması. Sınav kaydedilir.","fa":"Part 1 (۴ تا ۵ دقیقه): سؤال‌هایی درباره‌ی خودت و یک موضوع روزمره. Part 2 (۳ تا ۴ دقیقه): یک دقیقه آماده شدن، بعد تا دو دقیقه حرف زدن به‌تنهایی و بعد یک سؤال کوتاه. Part 3 (۴ تا ۵ دقیقه): بحث درباره‌ی سؤال‌های کلی. آزمون ضبط می‌شود."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"One move for each part","tr":"Her kısım için bir hamle","fa":"برای هر بخش یک حرکت"},"steps":[{"en":"Part 1: answer, then add when, how often or why.","tr":"Part 1: cevapla, sonra ne zaman, ne sıklıkla ya da neden ekle.","fa":"Part 1: جواب بده، بعد بگو کی، هر چند وقت یک بار یا چرا."},{"en":"Part 2: describe the place from near to far, using colours, sizes and sounds.","tr":"Part 2: yeri yakından uzağa doğru, renkler, büyüklükler ve seslerle anlat.","fa":"Part 2: مکان را از نزدیک به دور، با رنگ، اندازه و صدا توصیف کن."},{"en":"Part 2: end with your feelings and why the moment mattered.","tr":"Part 2: duygularınla ve o anın neden önemli olduğuyla bitir.","fa":"Part 2: با احساست و اینکه چرا آن لحظه مهم بود تمام کن."},{"en":"Part 3: give a view, a reason, an example, and the other side.","tr":"Part 3: bir görüş, bir neden, bir örnek ve karşı tarafı ver.","fa":"Part 3: یک نظر، یک دلیل، یک مثال و طرف مقابل را بگو."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Describing a view","tr":"Bir manzarayı anlatmak","fa":"توصیف یک منظره"},"table":{"headers":{"en":["Use","Example"],"tr":["Kullanım","Örnek"],"fa":["کاربرد","مثال"]},"rows":[["what is near","Right below us was the old town, with its red roofs."],["what is far","In the distance, you could just make out the mountains."],["size and shape","The river looked like a thin silver line."],["feeling","It made me feel very small, but in a good way."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A Part 3 answer, step by step","tr":"Bir Part 3 cevabı, adım adım","fa":"یک جواب Part 3، قدم به قدم"},"instruction":"Examiner: \"Do adverts give young people unrealistic ideas about beauty?\"","item":"Answer with four moves.","answer":"I think they often do. Most of the photos in adverts are edited, so nobody really looks like that. A friend’s younger sister, for example, stopped posting photos because she felt ugly by comparison. That said, some brands now use more ordinary models, which is a step in the right direction.","walk":[{"en":"View: \"I think they often do.\"","tr":"Görüş: \"I think they often do.\"","fa":"نظر: «I think they often do.»"},{"en":"Reason and example: edited photos; the friend’s sister.","tr":"Neden ve örnek: düzenlenmiş fotoğraflar; arkadaşın kız kardeşi.","fa":"دلیل و مثال: عکس‌های ویرایش‌شده؛ خواهر کوچک دوست."},{"en":"The other side: some brands use ordinary models.","tr":"Karşı taraf: bazı markalar sıradan modeller kullanıyor.","fa":"طرف مقابل: بعضی برندها از مدل‌های معمولی استفاده می‌کنند."}]},"quick":{"prompt":"Part 1. Examiner: \"Do you often go to cafés?\" Which answer is best?","options":["Yes, I do.","Cafés have become very popular in many countries in recent years.","Quite often, maybe twice a week. There’s a small one near my office where I meet a friend on Fridays."],"correct":2,"why":{"en":"An answer, how often and a detail. \"Yes, I do.\" is too short; the last answer is not about you.","tr":"Bir cevap, ne sıklıkla ve bir ayrıntı. \"Yes, I do.\" çok kısa; son cevap seninle ilgili değil.","fa":"یک جواب، تعداد دفعه‌ها و یک جزئیات. «Yes, I do.» خیلی کوتاه است؛ جواب آخر درباره‌ی تو نیست."}},"remember":{"en":"Part 1 personal, Part 2 near to far and how you felt, Part 3 balanced views about people in general.","tr":"Part 1 kişisel, Part 2 yakından uzağa ve ne hissettiğin, Part 3 genel olarak insanlar hakkında dengeli görüşler.","fa":"Part 1 شخصی، Part 2 از نزدیک به دور و احساست، Part 3 نظرهای متعادل درباره‌ی آدم‌ها به‌طور کلی."},"type":"explain","id":"c-x10-s-e","course":"ielts-exams","exam":"exam-10","unit":"x10-s"},"sets":{"title":{"en":"The Speaking test","tr":"Speaking sınavı","fa":"آزمون Speaking"},"note":{"en":"Do the three parts in order, without a break, as in the real test. Record yourself if you can, then use the self-check under each part.","tr":"Gerçek sınavdaki gibi üç kısmı sırayla ve ara vermeden yap. Yapabilirsen kendini kaydet, sonra her kısmın altındaki öz değerlendirmeyi kullan.","fa":"سه بخش را به ترتیب و بدون مکث انجام بده، مثل آزمون واقعی. اگر می‌توانی صدایت را ضبط کن و بعد از خودارزیابیِ زیر هر بخش استفاده کن."},"sequential":true,"examinerVoice":{"accent":"British (standard Southern)","gender":"F","tts":{"engine":"kokoro","voice":"bf_emma"},"role":"Examiner"},"sets":[{"part":"Part 1","ctx":["S1-frame","S1-food"],"minutes":[4,5],"title":{"en":"Part 1: about you, then tea and coffee","tr":"Part 1: senin hakkında, sonra çay ve kahve","fa":"Part 1: درباره‌ی خودت، بعد چای و قهوه"},"examinerIntro":["Good afternoon. My name is Clare Holden. Can you tell me your full name, please?","Thank you. And can I see your identification, please?","Thank you. Now, in this first part, I’d like to ask you some questions about yourself."],"frame":["Do you work or are you a student?","What is a typical day like for you?","Do you live alone or with other people?"],"topicIntro":"Now let’s talk about tea and coffee.","questions":["Do you prefer tea or coffee?","When do you usually have a hot drink?","Do you often go to cafés with friends? [Why/Why not?]","Have your drinking habits changed since you were a child?"],"model":"Q: Do you prefer tea or coffee?\nA: Tea, definitely. I have about five cups a day, usually black with a slice of lemon. Coffee makes me feel a bit nervous.\n\nQ: When do you usually have a hot drink?\nA: First thing in the morning, before I do anything else, and then again in the middle of the afternoon, when I start to feel tired.\n\nQ: Do you often go to cafés with friends?\nA: Quite often, maybe once a week. There’s a small place near my office with big sofas, and it’s a nice way to catch up after work.\n\nQ: Have your drinking habits changed since you were a child?\nA: A lot. As a child I drank mostly milk and fruit juice, and I thought tea was a drink for old people. Now I can’t start the day without it.","moves":[{"label":{"en":"Answer first","tr":"Önce cevap","fa":"اول جواب"},"example":"Tea, definitely."},{"label":{"en":"Add when, how often or why","tr":"Ne zaman, ne sıklıkla ya da neden ekle","fa":"بگو کی، چند وقت یک بار یا چرا"},"example":"I have about five cups a day, usually black with a slice of lemon."},{"label":{"en":"Then and now","tr":"O zaman ve şimdi","fa":"آن موقع و حالا"},"example":"As a child I drank mostly milk... Now I can’t start the day without it."}],"selfCheck":[{"en":"I answered every question with two or three sentences.","tr":"Her soruyu iki üç cümleyle cevapladım.","fa":"به هر سؤال با دو سه جمله جواب دادم."},{"en":"I used frequency words: usually, once a week, first thing in the morning.","tr":"Sıklık kelimeleri kullandım: usually, once a week, first thing in the morning.","fa":"کلمه‌های تکرار را به کار بردم: usually، once a week، first thing in the morning."},{"en":"I contrasted the past and the present with \"As a child... Now...\".","tr":"Geçmişle bugünü \"As a child... Now...\" ile karşılaştırdım.","fa":"گذشته و حال را با «As a child... Now...» مقایسه کردم."}]},{"part":"Part 2","ctx":["S2-place"],"minutes":[3,4],"title":{"en":"Part 2: a high place with a good view","tr":"Part 2: güzel manzaralı yüksek bir yer","fa":"Part 2: جایی بلند با منظره‌ای زیبا"},"examinerIntro":["Now I’m going to give you a topic, and I’d like you to talk about it for one to two minutes. Before you talk, you’ll have one minute to think about what you’re going to say. You can make some notes if you wish. Do you understand?","Here’s some paper and a pencil for making notes, and here’s your topic. I’d like you to describe a high place you have visited that had a beautiful view.","All right? Remember you have one to two minutes for this. Don’t worry if I stop you. I’ll tell you when the time is up. Can you start speaking now, please?"],"card":{"task":"Describe a high place you have visited that had a beautiful view.","bullets":["where the place was","how you got there","what you could see from there","and explain how you felt when you were there"]},"prep":60,"talk":120,"roundingOff":["Do you prefer views of the countryside or of cities?"],"model":"I’d like to talk about a hill just outside my home town, which I climbed early one morning last spring with my younger brother.\n\nIt’s not a famous place at all. There’s no cable car or café at the top, just a narrow path through the woods and then a steep, rocky section at the end. We set off at about half past five, while it was still dark, because we wanted to see the sunrise. It took us just over an hour, and by the time we reached the top, my legs were shaking.\n\nBut the view was worth every step. Right below us was the old part of the town, with its red roofs and the church tower, and you could see the river winding through it like a thin silver line. Further away, there was a layer of mist lying over the fields, and in the distance, you could just make out the mountains on the other side of the valley, turning pink as the sun came up.\n\nAs for how I felt, it was a strange mixture. Partly I felt very small, looking at all those houses and imagining the people still asleep inside. But I also felt quite proud, because my brother and I had done something together that we had talked about for years. We sat there for nearly an hour without saying much, and I think that silence is what I remember most. I’ve been up there twice since, but never again at sunrise.","moves":[{"label":{"en":"Start with where and when","tr":"Nerede ve ne zaman ile başla","fa":"با کجا و کی شروع کن"},"example":"A hill just outside my home town, which I climbed early one morning last spring."},{"label":{"en":"Describe the view from near to far","tr":"Manzarayı yakından uzağa anlat","fa":"منظره را از نزدیک به دور توصیف کن"},"example":"Right below us was the old part of the town... In the distance, you could just make out the mountains."},{"label":{"en":"Spend time on the feeling line","tr":"Duygu satırına zaman ayır","fa":"روی خط احساس وقت بگذار"},"example":"Partly I felt very small... But I also felt quite proud..."}],"selfCheck":[{"en":"I covered all four lines of the card and spoke for close to two minutes.","tr":"Kartın dört satırının hepsini ele aldım ve iki dakikaya yakın konuştum.","fa":"هر چهار خط کارت را گفتم و نزدیک دو دقیقه حرف زدم."},{"en":"I described the view with positions and colours, not just a list.","tr":"Manzarayı yalnızca liste olarak değil, konumlar ve renklerle anlattım.","fa":"منظره را با جای چیزها و رنگ‌ها توصیف کردم، نه فقط با فهرست."},{"en":"I explained my feelings with a reason.","tr":"Duygularımı bir nedenle açıkladım.","fa":"احساسم را با دلیل توضیح دادم."}]},{"part":"Part 3","ctx":["S3-consumer"],"minutes":[4,5],"title":{"en":"Part 3: beauty, advertising and success","tr":"Part 3: güzellik, reklam ve başarı","fa":"Part 3: زیبایی، تبلیغات و موفقیت"},"examinerIntro":["We’ve been talking about a beautiful view, and I’d like to discuss with you one or two more general questions related to beauty."],"subtopics":[{"title":"Beauty and advertising","questions":["Why do so many adverts use attractive people?","Do adverts give young people unrealistic ideas about how they should look?","Why do people spend so much money on beauty products?"]},{"title":"Beauty and success","questions":["Does appearance help people to succeed at work?","Have ideas about beauty changed in your country in recent years?","Should schools teach children about how images in the media are edited?"]}],"model":"Q: Why do people spend so much money on beauty products?\nA: Mostly, I think, because of confidence. Many people genuinely feel better about themselves when they like the way they look, and that affects how they behave at work or with friends. Advertising plays a part too, of course: companies are very good at making us believe we need the latest cream or serum. That said, I’ve noticed that more people now prefer simple, cheaper products, so perhaps the attitude is slowly changing.\n\nQ: Does appearance help people to succeed at work?\nA: To some extent, yes, especially at the start. In an interview, first impressions matter, and someone who looks neat and confident may have an advantage. In jobs like sales, it can make a real difference. But in the long run, I’d say skills and reliability matter far more. A colleague who always delivers good work will be promoted, whatever they look like.","moves":[{"label":{"en":"Give a clear view","tr":"Net bir görüş ver","fa":"نظرت را روشن بگو"},"example":"To some extent, yes, especially at the start."},{"label":{"en":"Support it: reason + example","tr":"Destekle: neden + örnek","fa":"پشتیبانی کن: دلیل + مثال"},"example":"In an interview, first impressions matter... In jobs like sales, it can make a real difference."},{"label":{"en":"Show the other side","tr":"Karşı tarafı göster","fa":"طرف مقابل را نشان بده"},"example":"But in the long run, I’d say skills and reliability matter far more."}],"selfCheck":[{"en":"I gave a clear view in my first sentence.","tr":"İlk cümlemde net bir görüş verdim.","fa":"در جمله‌ی اولم نظر روشنی دادم."},{"en":"I used a balancing phrase: to some extent, that said, in the long run.","tr":"Dengeleyici bir ifade kullandım: to some extent, that said, in the long run.","fa":"یک عبارت متعادل‌کننده به کار بردم: to some extent، that said، in the long run."},{"en":"I talked about people in general, not only about myself.","tr":"Yalnızca kendimden değil, genel olarak insanlardan söz ettim.","fa":"درباره‌ی آدم‌ها به‌طور کلی حرف زدم، نه فقط خودم."}]}],"type":"sets","id":"c-x10-s-p","course":"ielts-exams","exam":"exam-10","unit":"x10-s"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"The view was breathtaking.\" Breathtaking means...","options":["very cold","extremely beautiful","hard to see"],"correct":1,"why":{"en":"Breathtaking = so beautiful that it surprises you.","tr":"Breathtaking = insanı şaşırtacak kadar güzel.","fa":"breathtaking یعنی آن‌قدر زیبا که شگفت‌زده‌ات کند."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase means \"partly true\"?","options":["to some extent","in the distance","in the long run"],"correct":0,"why":{"en":"To some extent = partly, up to a point.","tr":"To some extent = kısmen, bir noktaya kadar.","fa":"to some extent یعنی تا حدی."}},{"tests":"method","point":2,"prompt":"In Part 2, how can you make the description of a view clearer?","options":["List every object you saw","Give the height in metres","Move from what is near to what is far"],"correct":2,"why":{"en":"Near to far gives the listener a clear picture and a natural order.","tr":"Yakından uzağa anlatmak dinleyene net bir resim ve doğal bir sıra verir.","fa":"از نزدیک به دور گفتن تصویری روشن و ترتیبی طبیعی به شنونده می‌دهد."}},{"tests":"trap","point":2,"prompt":"Part 3: \"Does appearance matter at work?\" A candidate says: \"Yes, it does.\" What should come next?","options":["The next question","A reason, an example and possibly the other side","A story about a holiday"],"correct":1,"why":{"en":"A bare answer is too short for Part 3; develop it.","tr":"Yalın bir cevap Part 3 için çok kısa; geliştir.","fa":"جواب خالی برای Part 3 خیلی کوتاه است؛ گسترشش بده."}},{"tests":"method","point":3,"prompt":"Which sentence shows a balanced view?","options":["That said, skills matter far more in the long run.","Beauty is everything.","I never think about beauty."],"correct":0,"why":{"en":"\"That said\" introduces the other side and balances the answer.","tr":"\"That said\" karşı tarafı getirir ve cevabı dengeler.","fa":"«that said» طرف مقابل را می‌آورد و جواب را متعادل می‌کند."}}],"id":"c-x10-s-x","course":"ielts-exams","exam":"exam-10","unit":"x10-s"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
